B.ak3=new A.n(B.i,["Torna ad allenarti","Back to training","Vuelve a entrenar","Volte a treinar","Reprenez l'entra\xeenement","Zur\xfcck zum Training","\u0395\u03c0\u03ad\u03c3\u03c4\u03c1\u03b5\u03c8\u03b5 \u03c3\u03c4\u03b7\u03bd \u03c0\u03c1\u03bf\u03c0\u03cc\u03bd\u03b7\u03c3\u03b7","\u0639\u062f \u0644\u0644\u062a\u062f\u0631\u064a\u0628","Wr\xf3\u0107 do treningu","\xcentoarce-te la antrenament","Vissza az edz\xe9shez"],t.w)
