B.al8=new A.n(B.i,["COLORE TEMA","THEME COLOR","COLOR TEMA","COR DO TEMA","COULEUR TH\xc8ME","THEMENFARBE","\u03a7\u03a1\u03a9\u039c\u0391 \u0398\u0395\u039c\u0391\u03a4\u039f\u03a3","\u0644\u0648\u0646 \u0627\u0644\u062b\u064a\u0645","KOLOR MOTYWU","CULOARE TEM\u0102","T\xc9MA SZ\xcdN"],t.w)
